["ecp_female_desc"] = "UYRUĞU: İSRAİLLİ$NL;YAŞI: 29$NL;$NL;SÖYLENTİYE GÖRE HİLA, İSRAİL ORDUSUNDA ÇOK AĞIR BİR EĞİTİMDEN GEÇMİŞ. BUNU HERKESİN ÖNÜNDE İNKÂR ETMEYE DEVAM ETSE DE BAIN’İN ONU VE EŞİ ETHAN’I ÇETEYE DAVET ETMESİNDE MUTLAKA DİKKATİNİ ÇEKEN BİR ŞEY VARDI. RESMÎ AÇIKLAMAYA GÖRE FBI’LA İLGİLİ BAZI GELİŞMELER IŞIĞINDA ÇETENİN ÇOK İHTİYAÇ DUYDUĞU OLUMLU KAMUOYU DESTEĞİNİ SAĞLAMAK İÇİN GETİRİLDİLER. AMA ASIL NEDENİ... YALNIZCA BAIN KESİN OLARAK BİLİYOR.",
["ecp_male_desc"] = "UYRUĞU: AMERİKALI$NL;YAŞI: 32$NL;$NL;İNTERNETİN MEŞHUR GOLİATH’INA KARŞI BİR ÇEŞİT DAVİD OLAN ETHAN, BAIN’İN AKLINDAN NELER GEÇTİĞİNİN ASLA TAM OLARAK BİLİNEMEYECEĞİNİN KANITI. YETENEKLİ SOSYAL MEDYA YAYINCISI ETHAN VE EŞİ HİLA, BELGESEL ÇALIŞMALARIYLA BAZI KİŞİLERİN HUKUKİ ÖFKESİNİ ÜZERLERİNE ÇEKTİ. KENDİLERİNİ SAVUNMAK İÇİN KÜÇÜK BİR SERVET HARCAMAK ZORUNDA KALDILAR VE MADDİ AÇIDAN SAVUNMASIZ DURUMA DÜŞTÜLER. HALKLA İLİŞKİLER VE KİTLELERLE İLETİŞİM BECERİLERİ BAIN’İN İLGİSİNİ ÇEKTİ. BAIN, KAYIPLARINI TELAFİ ETME, SERVET VE ŞAN VAATLERİYLE ONU VE EŞİNİ PAYDAY’E KATILMAYA İKNA ETTİ.",
["eday1_brief"] = "THE ELEPHANT'IN HALKLA İLİŞKİLER EKİBİ, İKTİDARA BİRİKİMİ, LİDERLİĞİ VE DÜRÜSTLÜĞÜ SAYESİNDE GELDİĞİNİ SÖYLEYECEK AMA PALAVRA. O KAYPAK HERİF SENATOYA HİLEYLE GİRECEK; SİZ BURADA DEVREYE GİRİYORSUNUZ. PİER 39'DA KAMYONLAR VAR. BİRİNDE OY VERME MAKİNELERİ BULUNUYOR. KAMYONU BULUP GPS TAKİP CİHAZI TAKIN. SONRASINI YOLDA HALLEDECEĞİZ. DOĞAL OLARAK THE ELEPHANT, İŞİN KENDİSİNE KÖTÜ HABER OLARAK DÖNME İHTİMALİNİN OLABİLDİĞİNCE DÜŞÜK OLMASINI İSTİYOR. BU YÜZDEN YÜKLÜ KAMPANYA BÜTÇESİNDEN GİZLİ OPERASYON BONUSU İÇİN PARA AYIRMIŞ. SİZ SESSİZCE YAPIN, İYİ POLİTİKACIMIZ DA ÖDÜLÜNÜZÜN HAKKINI VERECEK.",
["eday2_brief"] = "KAMYONUN İZİNİ GOOSE ISLAND YAKINLARINDAKİ BİR DEPOYA KADAR SÜRDÜM. BURASI, OY VERME MAKİNELERİNİ SON DURAKLARINA GÖNDERMEKLE GÖREVLİ BİR DAĞITIM DEPOSU. BİRAZ TEKNİK SİHİRLE MAKİNELERİ THE ELEPHANT'IN BELEDİYE BAŞKANI ADAYINA, O KAYPAK ŞEREFSİZ MCKENDRİCK'E DAHA SICAK BAKAR HÂLE GETİRECEĞİZ. İÇERİ GİRİN, SİSTEMLERİNİ KIRIN, ÇIKIN. BASİT.",
["eday3_brief"] = "OY VERME MAKİNELERİYLE OYNAMAYI BAŞARAMAMIŞ OLABİLİRİZ AMA BU SEÇİME HÂLÂ HİLE KARIŞTIRABİLİRİZ. OYLAR VERİLDİ, ÇIKIŞ ANKETLERİ DE PEK UMUTLU DEĞİL. SONUÇLARIN OLDUĞU SUNUCUYU BOZARSAK YENİDEN SEÇİM YAPILMASINI SAĞLAYABİLİRİZ. AMA İŞİN PÜF NOKTASI ŞU: ŞÜPHE ÇEKMEMEK İÇİN YANDAKİ BANKAYI SOYUP BUNU SOYGUNUN YAN HASARI GİBİ GÖSTERECEĞİZ.",
["eday3_brief_skip1"] = "SİZİ PİSLİKLER, İŞARETLEDİĞİNİZ KAMYON YANLIŞMIŞ. O OY MAKİNELERİNİN ÖNÜNÜ KESMEYİ UNUTABİLİRİZ. ELEPHANT'I MEMNUN TUTMAK İÇİN BAŞKA BİR ŞEY DENEYECEĞİZ. OY VERME YERİNDEKİ SUNUCUYU BOZARAK SEÇİMİN YENİLENMESİNİ SAĞLAYABİLİRİZ. SPONSORUMUZA ŞÜPHE ÇEKMEMEK İÇİN YANDAKİ BANKAYI SOYUP BUNU KAZARA OLUŞAN BİR HASAR GİBİ GÖSTERECEĞİZ.",
["eday3_brief_skip2"] = "YÜKLEDİĞİNİZ SEVKİYAT BİLGİLERİNDEN DOĞRU KAMYONU BULAMADIM; OY VERME MAKİNELERİNİN ÖNÜNÜ KESEMEYECEĞİZ. AMA THE ELEPHANT'I YİNE DE MEMNUN EDEBİLİRİZ. OY VERME YERİNİN YANINDA BİR BANKA VAR. ORAYI VURACAĞIZ. DAHA DOĞRUSU ASIL HEDEFİNİZ, YAN TARAFTAKİ SEÇİM SONUÇLARININ BULUNDUĞU SUNUCU. BANKAYI VURUN, KASA DAİRESİNİ AÇIN, BİLDİĞİNİZ İŞLER. AMA ASIL AMACIN O OY VERME YERİNİ BERBAT ETMEK OLDUĞUNU UNUTMAYIN.",
["elp_bigoil_brf_intro_01"] = "BİLDİĞİNİZ GİBİ SİYASET KÜRESELDİR. KÜRESEL BİR GİRİŞİM İÇİN SİZE İHTİYACIM VAR.",
["elp_bigoil_brf_outro_01"] = "YAĞLANMIŞ MAKİNE GİBİ BEYLER, İLERİ.",
["elp_bigoil_brf_outro_02"] = "HASSAS BİR SAAT GİBİ BEYLER, TIKIR TIKIR İŞLEMEYE DEVAM EDİN. ",
["elp_bigoil_brf_speak_01"] = "BAĞLANTILARIMIZ YENİ BİR İCADIN ORTAYA ÇIKTIĞINI SÖYLÜYOR. SOĞUK FÜZYON ENERJİSİ, FOSİL YAKITLARIN SONU VE PETROL HOLDİNGLERİNİN ÖLÜMÜ. BİZİM İŞİMİZ RİSK YÖNETİMİ.",
["elp_bigoil_brf_speak_01b"] = "MUCİDİN PEŞİNDEKİ BİR EKİP HAKKINDA BİLGİM VAR. ONLARI BULUN, MUCİDİ BULUN VE TARİHİN O SAYFASINI KAPATIN. HIZLI VE TEMİZ OLSUN.",
["elp_bigoil_brf_speak_02"] = "DC'DE BİR YERDE YAŞAYAN ROSSY ADINDA BİR MUCİT, SUDAN UCUZA ENERJİ ÜRETMENİN YOLUNU BULMUŞ OLABİLİR.",
["elp_bigoil_brf_speak_02b"] = "BU CİHAZ BULUNUP MÜŞTERİME... 'DEĞERLENDİRME' İÇİN TESLİM EDİLMELİ. AYRICA YANLIŞ ELLERE GEÇMESİN DİYE TEKNİK BİLGİLER DE SİLİNMELİ.",
["elp_bigoil_brf_speak_03"] = "SOĞUK FÜZYON ENERJİSİ, MÜŞTERİLERİM İÇİN SIRADAKİ BÜYÜK FIRSAT OLABİLİR. NE YAZIK Kİ EN UMUT VERİCİ PROTOTİP ONLARIN DEĞİL. HENÜZ.",
["elp_bigoil_brf_speak_03b"] = "ONU BULUP BANA GETİRMENİZİ, İCAT EDİLDİĞİNE DAİR BÜTÜN İZLERİ SİLMENİZİ İSTİYORUM. NEREDEN BAŞLAYACAĞINIZI SÖYLEYECEĞİM.",
["elp_bigoil_cmc_01"] = "BEYLER, DÜNYAYI DEĞİŞTİRME FIRSATI SİZİ BEKLİYOR. EMEĞİNİZİN KARŞILIĞI OLACAK!",
["elp_bigoil_cmc_02"] = "BEYLER, PETROL DÜNYAMIZIN KANIDIR. ONSUZ ÖLÜRÜZ. AKMAYA DEVAM ETTİĞİNDEN EMİN OLMA VAKTİ.",
["elp_bigoil_cmc_03"] = "BEYLER, MEVCUT ENERJİ POLİTİKASINI SÜRDÜRMEK İSTEYEN LOBİCİLER YARDIMINIZI İSTİYOR. OLDUKÇA KÂRLI BİR İŞ. BENCE ÇAĞRILARINA CEVAP VERELİM.",
["elp_bigoil_cnc_01"] = "BEYLER, DÜNYAYI DEĞİŞTİRME FIRSATI SİZİ BEKLİYOR. EMEĞİNİZİN KARŞILIĞI OLACAK!",
["elp_bigoil_cnc_02"] = "BEYLER, PETROL DÜNYAMIZIN KANIDIR. ONSUZ ÖLÜRÜZ. AKMAYA DEVAM ETMESİNİ SAĞLAMA VAKTİ.",
["elp_bigoil_cnc_03"] = "BEYLER, ENERJİ POLİTİKASININ MEVCUT ÇİZGİSİNİ KORUMAK İSTEYEN LOBİCİLERİN YARDIMINIZA İHTİYACI VAR. GERÇEKTEN ÇOK KAZANÇLI. BENCE ÇAĞRILARINA CEVAP VERELİM.",
["elp_bigoil_debrief_01"] = "GÜVENLİ TESLİMAT İÇİN TEŞEKKÜRLER BEYLER. CİHAZ ŞİMDİ UZUN SÜRE TEST EDİLECEK... ÇOK UZUN SÜRE. BU ARADA PARANIZIN TADINI ÇIKARIN!",
["elp_bigoil_debrief_02"] = "BEYLER, ORTAK DOSTLARIMIZ OLDUKÇA MEMNUN KALMIŞ GÖRÜNÜYOR. BU İCADI HIZLICA TESLİM ETTİĞİNİZ İÇİN TEŞEKKÜRLER. DÜNYA ARTIK HER ZAMANKİ İŞLEYİŞİNE DÖNECEK.",
["elp_bigoil_debrief_03"] = "AZ ÖNCE GÖRDÜKLERİNİZİ UNUTUP ÖDÜLÜNÜZÜ SAYMAYA ODAKLANIN! BİG EİGHT SELAMLARINI GÖNDERİYOR.",
["elp_bigoil_debrief_04"] = "YAŞAM BİÇİMİMİZİ KORUDUĞUNUZ İÇİN TEŞEKKÜR EDERİM. PARA, ON MİLYON GALONLUK BİR PETROL SIZINTISI GİBİ SİZE DOĞRU AKIYOR.",
["elp_election_brf_outro_01"] = "İYİ OLAN KAZANSIN.",
["elp_election_brf_outro_02"] = "İYİ OLAN KAZANSIN.",
["elp_election_brf_speak_01"] = "OYLAMA YARIN BAŞLAYACAK. FARK YARATMAK İÇİN ŞİMDİ HAREKETE GEÇMELİYİZ. YENİ OY MAKİNELERİ LİMANA GELDİ.",
["elp_election_brf_speak_01b"] = "OYLARI BENİM TARAFIMA ÇEVİRMEK İÇİN YENİDEN PROGRAMLAMANIZ GEREK. YAZILIM SAĞLANDI. FARK EDİLMEDEN YAPIN.",
["elp_election_brf_speak_02"] = "BEYLER, BUGÜN OY KULLANIYORUZ. DERLER Kİ: BİR ADAM, BİR OY. BEN DİYORUM Kİ: DÖRT ADAM, BİR SÜRÜ OY. BÖLGEMDEKİ OY MAKİNELERİNE HİLE KARIŞTIRMANIZI İSTİYORUM.",
["elp_election_brf_speak_02b"] = "ONLARI LİMANDA BULUN VE ALIŞVERİŞ MERKEZİNDEKİ VARIŞ YERLERİNE ULAŞMADAN YENİDEN PROGRAMLANDIKLARINDAN EMİN OLUN.",
["elp_election_brf_speak_03"] = "D.C. HALKININ DOĞRU OY VERMESİNE YARDIM EDİN. LİMANDAKİ OY MAKİNELERİNİ BULUP DAĞITILMADAN ELE GEÇİRMELİYİZ. MAKİNELER OYLARI BANA ÇEVİRMELİ!",
["elp_election_cmc_01"] = "BEYLER, SEÇİM KRİTİK BİR NOKTADA. DOĞRU TARAFA YÖNELTMEME YARDIM ETMELİSİNİZ.",
["elp_election_cmc_02"] = "BEYLER, DC'DE OY VERME İŞLEMİ BAŞLAMAK ÜZERE. BİRKAÇ SEÇMENİ DOĞRU TARAFA ÇEKMELİYİZ. YARDIMINIZ DOKUNABİLİR.",
["elp_election_cmc_03"] = "BEYLER, YENİ OY MAKİNELERİ DC'YE GELDİ. BİRAZ DAHA BENİM LEHİME ÇALIŞMALARI İÇİN KURCALAMALISINIZ. SESSİZCE YAPIN.",
["elp_election_debrief_01"] = "TAM BİR USTALIK ESERİ, DOSTLARIM! SAYENİZDE YARIN DAHA İYİ BİR SONUÇ ALACAĞIZ. ÇOK MAKBULE GEÇTİ!",
["elp_election_debrief_02"] = "ÇOK YARATICIYDI. KİMSE BİR ŞEYDEN ŞÜPHELENMEDİ. OY MAKİNELERİ DE DEVREDE, BÜYÜK OYNAMAYA HAZIR! TEŞEKKÜRLER.",
["elp_election_debrief_03"] = "ÇÖZMEK İÇİN ÇOK ALIŞILMADIK BİR YOL. SOYGUN İÇİNDE SOYGUN. ZEKÂNIZI TAKDİR EDİYORUM. OYLAR ARTIK DOĞRU KULLANILACAK!",
["elp_election_debrief_04"] = "ARTIK YÜKSEK MEVKİLERDE DOSTLARINIZ OLDUĞU İÇİN TEBRİKLER! SENATÖRÜNÜZÜ BÖYLESİNE DOĞRUDAN DESTEKLEDİĞİNİZ İÇİN TEŞEKKÜR EDERİM. SİZİ HAYAL KIRIKLIĞINA UĞRATMAYACAĞIM!",
["elp_framing_brf_intro_01"] = "BİR MESELEDE YARDIMINIZA İHTİYACIM VAR...",
["elp_framing_brf_outro_01"] = "BOL ŞANS BEYLER.",
["elp_framing_brf_speak_01"] = "SENATÖR BORRİCO SİYASETTE VE İŞ DÜNYASINDA İLERLİYOR. BİR ÜLKEYLE KÂRLI BİR SİLAH ANLAŞMASI YAPTIĞINI ÖĞRENDİM. BU ÜLKE ONA SAF ALTINLA ÖDEME YAPMIŞ.",
["elp_framing_brf_speak_01b"] = "ÇATI KATINDAKİ DAİRESİNE SIZIP SİYASİ AÇIDAN TARTIŞMALI EŞYALAR YERLEŞTİRMENİZİ İSTİYORUM. ARDINDAN SİLAH ANLAŞMASINDAN ALDIĞI ALTINI ÇIKARACAKSINIZ.",
["elp_framing_brf_speak_01c"] = "BUNU SESSİZCE BAŞARIRSANIZ PARTİSİ ZARAR GÖRECEK, DOLAYISIYLA SİZE ÖDENECEK PARA DA EPEY ARTACAK.",
["elp_framing_brf_speak_02"] = "SENATÖR BORRİCO, BİRAZ ŞAİBELİ BİR ÜLKEYLE ULUSAL ÇAPTA KAZANÇLI BİR SİLAH ANLAŞMASI YAPTI. ÇATI KATINDAKİ DAİRESİNE GİRMENİN BİR YOLUNU BULUN.",
["elp_framing_brf_speak_02b"] = "ALTINLARINI ALMAK İÇİN BASKIN YAPIN AMA OLABİLDİĞİNCE SESSİZ OLUN. BAĞLANTIMIZI KİMSE ÖĞRENMEMELİ. ONU VE PARTİSİNİ SUÇLU GÖSTERİRSENİZ ÖDEMEYİ CİDDİ ÖLÇÜDE ARTIRIRIM.",
["elp_framing_brf_speak_03"] = "SENATÖR BORRİCO ŞU KÜÇÜK ALTIN KARŞILIĞI SİLAH ANLAŞMASINI TAMAMLADIĞINA GÖRE ARTIK TAM KIVAMINDA.",
["elp_framing_brf_speak_03b"] = "DAİRESİNE GİZLİCE GİRMENİN BİR YOLUNU BULUN, ALTINI ÇALIN VE ALEYHİNE DELİL YERLEŞTİRİN. SONRA FARK EDİLMEDEN AYRILIN.",
["elp_framing_cmc_01"] = "BEYLER, SİZE ALTIN DEĞERİNDE BİR FIRSATIM VAR. SİYASET VE SANATIN EN GÜZEL HÂLİ.",
["elp_framing_cmc_02"] = "BEYLER, BİR RAKİBİ SİYASET SAHNESİNDEN SİLMEK İÇİN BECERİKLİ ELLERİNİZE İHTİYACIM VAR. ÖDÜL ALTIN DEĞERİNDE.",
["elp_framing_cmc_03"] = "BEYLER, BİRİNİN SERVETİNİ PARTİMİN EN İYİ... ÇIKARLARINA HİZMET EDECEK ŞEKİLDE AKTARMAMDA YARDIMINIZA İHTİYACIM VAR.",
["elp_framing_cnc_01"] = "BEYLER, SİZİN İÇİN ALTIN BİR FIRSATIM VAR. SİYASETLE SANATIN EN İYİSİ.",
["elp_framing_cnc_02"] = "BEYLER, BİR RAKİBİ SİYASET SAHNESİNDEN SİLMEK İÇİN BECERİKLİ ELLERİNİZE İHTİYACIM VAR. ÖDÜL ALTIN DEĞERİNDE.",
["elp_framing_cnc_03"] = "BEYLER, BİRİNİN SERVETİNİ PARTİMİN EN İYİ... ÇIKARLARINA HİZMET EDECEK ŞEKİLDE AKTARMAMA YARDIM ETMELİSİNİZ.",
["elp_framing_debrief_01"] = "ALTI HABERLERİ BU HİKÂYEYE BAYILDI, REDDİT DE NOEL AĞACI GİBİ IŞILDADI! SENATÖRÜN İŞİ BİTTİ. GANİMETİNİZİN TADINI ÇIKARIN BEYLER; PARTİM MEMNUN. ",
["elp_framing_debrief_02"] = "SİZİN YA DA BENİM KARIŞTIĞIMIZA DAİR TEK İZ YOK. SENATÖR ARTIK HALKIN GÖZÜNDE HIRSIZ BİR UYUŞTURUCU BARONU. PARTİSİ TELAŞ İÇİNDE. SİZE ŞAPKA ÇIKARIYORUM BEYLER!",
["elp_framing_debrief_03"] = "ALTININ TADINI ÇIKARACAĞINIZA EMİNİM. SENATÖR SEÇİM YARIŞINDAN ÇEKİLİYOR. DAHA FAKİR, HÂLÂ HİÇBİR ŞEYDEN HABERSİZ. İYİ İŞ!",
["elp_framing_debrief_04"] = "SANAT ESERLERİNİ SIZMA YÖNTEMİ OLARAK KULLANMAK HOŞ BİR DOKUNUŞTU. ÖZELLİKLE TELEVİZYONDAKİ SENATÖR VE UYUŞTURUCU GÖRÜNTÜLERİNE BAYILDIM. ÇOK MEMNUNUM! İYİ GÜNLER.",
["elp_quote_set_a_01"] = "SİYASET EN İYİ HÂLİNDE BİLE KİRLİ BİR İŞTİR, DEĞİL Mİ? BAZEN TEMİZLİKTE YARDIM EDECEK İNSANLARA İHTİYAÇ DUYARSIN.",
["elp_quote_set_a_02"] = "BENİM GİBİ SİYASETÇİLER İŞLERİNE GELENİ DEĞİL, GEREKLİ OLANI YAPAR... GEREKLİ OLAN DA KİRLİ OLABİLİR.",
["elp_quote_set_a_03"] = "KENDİMİ PEK SİYASETÇİ SAYMAM. KENDİMİ TAKIM ELBİSELİ BİR SAVAŞÇI OLARAK GÖRÜRÜM.",
["elp_quote_set_a_04"] = "SİYASETTE DEĞİŞİMİ YARATMAK İÇİN DEĞİŞİMİN KENDİSİ OLMALISINIZ.",
["elp_quote_set_a_05"] = "BEN KİM MİYİM? TANIDIĞINIZ BÜTÜN SİYASETÇİLERİN TAM TERSİYİM. ",
["elp_quote_set_a_05_alt"] = "BEN KİM MİYİM? TANIDIĞINIZ BÜTÜN SİYASETÇİLERİN TAM TERSİYİM... OROSPU ÇOCUĞU!",
["elp_quote_set_a_06"] = "BENİM İÇİN ÖNEMLİ OLAN İNSANLARIN HAYATLARINI CİDDİYE ALMASIDIR. SONUÇTA SİYASET BUNDAN İBARETTİR: CİDDİ OL VE ORADA BULUN.",
