["gus_quote_set_a_05"] = "AKLINIZDA OLSUN: BANA İHANET EDERSENİZ SİZİ DİŞLERİNİZDEN BİLE TANINAMAYACAK ŞEKİLDE ORTADAN KALDIRABİLECEK GÜCÜM VAR.",
