["hct_firestarter_brf_outro_01"] = "PARALARININ KÜLLERİ GÖZLERİNİ KAPLASIN İSTİYORUM. İŞE KOYULUN.",
["hct_firestarter_brf_speak_01"] = "MENDOZA KARTELİ BİZİ TEHDİT EDİYOR. AMA BU ŞEHİR BİZİM. GÜÇ BURADA VE ONU BİZ KONTROL EDİYORUZ. ASIL TEHDİDİN KİM OLDUĞUNU GÖSTERECEĞİZ.",
["hct_firestarter_brf_speak_02"] = "MENDOZA KARTELİ, DC ÜZERİNDEN YIĞINLA SİLAH GEÇİRİYOR. BURADAKİ SİLAH DEPOLARINDAN BİRİNİ VURUP ASKERLERİNİ ZAYIFLATMANIZI İSTİYORUZ.",
["hct_firestarter_brf_speak_02b"] = "O İŞ BİTİNCE BURADAKİ NAKİT REZERVLERİNİ BULUP YAKMANIZI İSTİYORUZ. ONLARA KÜLDEN BAŞKA BİR ŞEY BIRAKMAYIN.",
["hct_firestarter_brf_speak_03"] = "MENDOZA'LARIN NAKİT AKIŞI TAMAMEN DURSUN İSTİYORUZ. BÜTÜN NAKİT REZERVLERİ BURADA, DC'DE. ULAŞMAK İÇİN SİLAH DEPOLARINI YOK EDİP ASKERLERİNİ SİLAHSIZ BIRAKMALIYIZ.",
["hct_firestarter_brf_speak_03b"] = "SONRA BANKALARINA GİDİP BÜTÜN PARALARINI YAKABİLİRSİNİZ. ONLARA HİÇBİR ŞEY BIRAKMADAN.",
["hct_firestarter_brf_speak_04"] = "MENDOZA'LARIN NAKİT AKIŞI HAKKINDA BİLGİMİZ VAR. AMERİKA'DAKİ OPERASYONLARINDAN 100 MİLYON DOLARIN ÜZERİNDE KAZANIYORLAR. BİR MESAJ VERMEK İSTİYORUZ: PARALARI DA SİLAHLARI DA ARTIK BİR İŞE YARAMIYOR.",
["hct_firestarter_brf_speak_04b"] = "ÖNCE ASKERLERİNE VURUN, SİLAHLARINI YOK EDİN. SONRA GİZLİ BANKALARINI BULUN. FBI ONUN HAKKINDA HER ŞEYİ BİLİYOR.",
["hct_firestarter_cnc_01"] = "KARTEL YİNE YARDIMINIZI İSTİYOR. FUTBOLDA DEDİĞİNİZ GİBİ, ŞİMDİ HÜCUMA GEÇİYORUZ. LAS MENDOZAS VE FBI, ZAYIFKEN BENİ ORTADAN KALDIRMADIKLARINA PİŞMAN OLACAK. ÇÜNKÜ ARTIK GÜÇLÜYÜM.",
["hct_firestarter_cnc_02"] = "FBI'A VE OROSPULUK YAPAN MENDOZA'LARA AÇIK BİR MESAJ GÖNDERMEK İSTİYORUM. KATKIDA BULUNABİLİRSİNİZ.",
["hct_firestarter_cnc_03"] = "PARA, BİLGİ VE KAN İÇİN MENDOZA KARTELİNİ SERT VURUYORUZ. ARTIK BİZİM İÇİN ÇOK FAYDALISINIZ.",
["hct_firestarter_debrief_01"] = "GÜNEYDEN HABERLER GELİYOR. MENDOZA'LAR KENDİ AİLELERİNE BİLE PARA YETİŞTİREMİYORMUŞ. GÜZEL.",
["hct_firestarter_debrief_02"] = "MENDOZA'LARIN ABD'DEKİ PARASI YOK OLDU. İYİ İŞ ÇIKARDINIZ. TABİİ BURADA DURMAYACAĞIZ. SİZİ YENİDEN ARAYACAĞIM.",
["hct_firestarter_debrief_03"] = "FBI VE MENDOZA'LAR ŞİMDİ TELAŞ İÇİNDE. ZAYIFLADILAR AMA ÖLMEDİLER. ONU SONRA HALLETMEMİZ GEREKECEK. HABERLEŞİRİZ.",
["hct_firestarter_debrief_04"] = "MENDOZA'NIN ÖRGÜTÜNE ÇİVİLER ÇAKTIK. BİZE YAPACAKLARI GİBİ ONLARI ÇARMIHA GERDİK. MAAŞ YOKSA ÖRGÜT DE YOK. FBI'IN PENÇESİ GEVŞİYOR, MENDOZA'LAR MEVZİ KAYBEDİYOR.",
