["hct_generic_debrief_outro_03"] = "OLAĞANÜSTÜ YETENEKLİSİNİZ. HAYAL KIRIKLIĞINA UĞRAMADIM.",
["hct_generic_debrief_outro_04"] = "AÇIK SÖZLÜ OLDUĞUNUZ İÇİN TEŞEKKÜRLER.",
["hct_quote_set_a_01"] = "BENİM ADIM HECTOR MORALEZ. İŞ İNSANIYIM. AÇIKÇASI BAŞKA BİR ŞEKİLDE ANILMAKTAN RAHATSIZ OLURUM. ",
["hct_quote_set_a_02"] = "KOLOMBİYA'DA DOĞDUM AMA BURADA, WASHINGTON DC'DE KÜÇÜK BİR İTHALAT-İHRACAT İŞİ KURARAK OLDUKÇA BAŞARILI OLDUM. GÖREVİMİN, İNSANLARIN DEĞERLİ ŞEYLERİ MALİYETİNE EDİNMESİNE YARDIM ETMEK OLDUĞUNU HİSSEDİYORUM.",
["hct_quote_set_a_02b"] = "MÜTEVAZI BİR HEDEF, KABUL EDİYORUM AMA HOŞUMA GİDİYOR.",
["hct_quote_set_a_03"] = "KADERE İNANMAM. İNANSAYDIM ELDE ETTİKLERİMİN HİÇBİRİ BANA GELMEZDİ.",
["hct_quote_set_a_04"] = "DÜNYADA O KADAR ÇOK APTAL SUÇLU VAR Kİ AKILLI OLMAK NİSPETEN KOLAY. ÇOĞU İNSANIN HAREKETE GEÇMEYİ SEÇTİĞİ YERDE BİRAZ DÜŞÜNMEK YETERLİ.",
["hct_quote_set_a_05"] = "HAYATIMDA EN ÇOK PİŞMAN OLDUĞUM ŞEY, GENÇLİĞİMİZDE CARLİTO MENDOZA'YA MERHAMET ETMİŞ OLMAM OLABİLİR. KARŞILIĞINI KANLA ÖDEDİM... BİR DAHA ASLA BÖYLE BİR HATA YAPMAYACAĞIM.",
["hct_rats_brf_outro_01"] = "ACELE EDİN, VAKTİNİZ YOK. İŞE KOYULUN.",
["hct_rats_brf_speak_01"] = "MENDOZA KARTELİ, ORMANDAKİ MET LABORATUVARIMIZA SALDIRIYOR. ACIMASIZLAR AMA APTALLAR. NE KADAR YANLIŞ YAPTIKLARINI GÖSTERECEĞİZ.",
["hct_rats_brf_speak_02"] = "RİCHMOND KIRSALINDAKİ METAMFETAMİN LABORATUVARIMIZ SALDIRI ALTINDA. MENDOZA KARTELİNİN SON ÇARESİZ HAMLESİ. ORAYI KORUMAMIZ VE AŞÇILARIMIZIN HAZIRLADIĞI METAMFETAMİNİ GÜVENE ALMAMIZ GEREKİYOR.",
["hct_rats_brf_speak_02b"] = "AŞÇILARIN İŞİNİN BİTMESİNİ SAĞLAYIN. ONLARA HİÇBİR ŞEY VERMEYİN.",
["hct_rats_brf_speak_03"] = "MENDOZA'LARIN KAÇTIĞINI BİLİYORUZ. MİSİLLEME İÇİN BİZE SON BİR SALDIRI YAPIYORLAR GİBİ. MET LABORATUVARIMIZ SALDIRI ALTINDA. METİ VE AŞÇILARI KURTARIN. DÜŞMANA NASIL DAVRANILACAĞINI BİLİYORSUNUZ. YAPIN.",
["hct_rats_cnc_01"] = "RAKİPLERİMİZ MENDOZA'LAR BATAN GEMİDEN KAÇAN SIÇANLAR GİBİ KAÇIYOR. YİNE DE KÖŞEYE SIKIŞMIŞ HER HAYVAN KADAR TEHLİKELİLER. METAMFETAMİN LABORATUVARIMIZI NE PAHASINA OLURSA OLSUN KORUYUN.",
["hct_rats_cnc_02"] = "MENDOZA KARTELİ D.C.'DEKİ METAMFETAMİN OPERASYONUMUZA SALDIRIYOR. YA CESARETLENDİLER YA DA ÇARESİZ KALDILAR. ORAYA GİDİN, PİŞMAN EDİN ONLARI.",
["hct_rats_cnc_03"] = "AŞÇILARIMIZDAN TELEFON ALDIM. MENDOZA KARTELİ, TAŞRADAKİ İŞLETMEMİZE SALDIRMAYI PLANLIYOR. BAŞARAMASINLAR. HEMEN ORAYA GİDİN.",
["hct_rats_debrief_01"] = "MİNNETTARIM, BENİ MAHCUP ETTİNİZ. GÜZEL İŞİNİZ KARTELİMİ HEM İTİBAR HEM SERVET AÇISINDAN YÜKSELTTİ. BEN DE KARTEL DE BUNU UNUTMAYACAĞIZ.",
["hct_rats_debrief_02"] = "OTOBÜSTE BÜTÜN MENDOZA TEĞMENLERİ VARDI. KARTELİM İÇİN BÜYÜK ADALET VE SAYGI SAĞLADINIZ. BİR ARA KOLOMBİYA'YA GELMELİSİNİZ DOSTLAR. ",
["hct_rats_debrief_03"] = "MENDOZA KARTELİNİN ABD'DEKİ GELECEĞİ SONA ERDİ. HEPSİ SİZİN SAYENİZDE. BURALARDA HERKES SİZİ KONUŞUYOR. TEŞEKKÜR EDERİM.",
["hct_rats_debrief_04"] = "MENDOZA AİLESİNİN İLERİ GELENLERİ HEPİNİZİN ÖLÜMÜNE YEMİN ETTİ... BU, KARTELİMİZİN ABD'DEKİ GELECEĞİNDE ÖNEMLİ BİR ETKİ YARATTIĞINIZIN İYİ BİR İŞARETİ. HER ŞEY İÇİN ÇOK TEŞEKKÜRLER ÇOCUKLAR...",
["hct_watchdogs_brf_speak_01"] = "DOSTLARIM, KANUN BİZE YETİŞMEDEN KOKAİNİMİZİ DC'DEN HIZLA ÇIKARMAMIZ GEREKİYOR. SİZ SİGORTA EKİBİ OLACAKSINIZ.",
["hct_watchdogs_brf_speak_02"] = "ET KAMYONUNA BİNİP SEVKİYATIMIZA LİMANA KADAR EŞLİK EDECEKSİNİZ. ADAMLARIM KOKAİNİ İNDİRECEK. MALLARI HIZLA TAŞIMAK İÇİN BİR SÜRAT TEKNESİ HAZIR BEKLEYECEK.",
["hct_watchdogs_brf_speak_02b"] = "BUNUN GERÇEKLEŞMESİNİ SAĞLAYIN. OLMAZSA DA DOĞAÇLAMADA İYİ OLDUĞUNUZU SÖYLEDİLER.",
["hct_watchdogs_brf_speak_03"] = "UYUŞTURUCUYLA BİRLİKTE GİDECEKSİNİZ. MALIMIN LİMANA ULAŞIP SÜRAT TEKNESİNE YÜKLENMESİNİ SAĞLAYACAKSINIZ... ",
["hct_watchdogs_brf_speak_03b"] = "BU ARADA ET KAMYONUMUN BUZDOLABI KONFORUNUN TADINI ÇIKARIP BİRAZ SERİNLEYEBİLİRSİNİZ. ÇÜNKÜ ORTAM ISINACAK...",
["hct_watchdogs_brf_speak_04"] = "FBI VE RAKİP KARTELİMİZ MENDOZA'LARIN D.C.'DEKİ KOKAİN TEDARİKİMİZE SALDIRDIĞINI BİLİYORUZ. BU NAKİLLE GİTMENİZİ VE GÜVENLİĞİNİ SAĞLAMANIZI İSTİYORUZ. LİMANDAKİ TEKNEMİZE ULAŞTIĞINDAN EMİN OLUN.",
["hct_watchdogs_brf_speak_05"] = "SİZİ DURDURMAYA ÇALIŞAN OLURSA, MENDOZA, POLİS, HER KİMSE, UYGUN ŞEKİLDE HALLEDİN. TOPLUMUN ONAYLAYACAĞI BİR YÖNTEM OLMASI GEREKMİYOR.",
["hct_watchdogs_brf_speak_05b"] = "TEK İSTEDİĞİM, BANA AİT OLANI GİTMESİ GEREKEN YERE ULAŞTIRMANIZ. NE OLURSA OLSUN BUNU YAPMALISINIZ. NE OLURSA OLSUN!",
["hct_watchdogs_cnc_01"] = "BU BİR NAKLİYE GÜVENLİĞİ İŞİ. ÇOK ÖNEMLİ.",
["hct_watchdogs_cnc_02"] = "KARTEL BU NAKLİYE KAMYONLARININ TESLİMAT İÇİN LİMANA SAĞ SALİM ULAŞMASINI İSTİYOR...",
["hct_watchdogs_cnc_03"] = "ÜRÜNÜMÜZÜN LİMANA ULAŞMASI GEREKİYOR. MUHAFIZ LAZIM. SİZ BURADA DEVREYE GİRİYORSUNUZ...",
["hct_watchdogs_debrief_01"] = "KARTEL MEMNUN. İYİ İŞ ÇIKARDINIZ. KOKAİN D.C.'DEN AYRILDI, ARTIK GÜVENDE.",
["hct_watchdogs_debrief_02"] = "KOKAİN ARTIK DAĞITICILARIN ELİNDE, HER ŞEY YOLUNDA. EMEĞİNİZİN MEYVESİNİN TADINI ÇIKARIN.",
["hct_watchdogs_debrief_03"] = "DURUMUMUZ ARTIK DAHA AZ ZOR. KOKAİN TEDARİKİ TEHDİT ALTINDA DEĞİL. ŞİMDİ DÜŞMANLARIMIZA KARŞI HAREKETE GEÇECEĞİZ. ÖNÜMÜZE KİM ÇIKARSA.",
["hct_watchdogs_debrief_04"] = "PARANIZ GÖNDERİLDİ. YENİDEN GÖRÜŞECEĞİZ ÇÜNKÜ ARTIK BU ÇATIŞMA KARŞI TARAFI YOK ETME MESELESİ. TELEFONLARINIZ AÇIK OLSUN.",
["heist_airport_briefing"] = "TAMAM, HAVAALANI TEPENİN HEMEN AŞAĞISINDA. ÇİTİ KESİP KUTULARIN BULUNDUĞU KAMYONUN OLDUĞU HANGARI BULUN. MENDOZAS MUHTEMELEN ORADADIR. SİLAHLARI MİNİBÜSE GETİRİN; YAPAMIYORSANIZ ELLERİNDE KALMASIN. ÇATIŞMADAN PES ETMEYECEKLER. ORTALIK KARIŞIRSA SİLAHLARI YOK EDİN.",
