["heist_vit_crimenet"] = "TÜM SOYGUNLARIN EN BÜYÜĞÜ. BUNUN İÇİN EĞİTİM GÖRDÜNÜZ. LANET WHİTE HOUSE! BÜTÜN SORUNLARIMIZIN CEVABI İÇERİDE. CEVABIN ÖNEMLİ BİR PARÇASI DA BİR DİZİ BELGE: HÂLÂ YASAL VE GEÇERLİ AMA ÜSTLERİNDE HİÇ İSİM OLMAYAN BAŞKANLIK AF BELGELERİ! ALABİLİRSENİZ HİÇBİR CEZA ALMADAN KURTULUP EMEKLİ OLABİLİRSİNİZ.$NL;$NL;» WHİTE HOUSE'A GİR$NL;» OVAL OFİS'E GİR$NL;» BAŞKANIN ANAHTAR KARTINI AL$NL;» PEOC'A GİR VE KASA DAİRESİNİ AÇ$NL;» BAŞKANLIK AF BELGELERİNİ ÇAL VE KAÇ",
["heist_watchdogs_1_briefing"] = "BU İŞTE BEKÇİLİK YAPIYORUZ.$NL;$NL;SAĞLAM BİR CEKET GİYİN VE DAHA DA SAĞLAM SİLAHLAR GETİRİN. HECTOR'IN SEVKİYATLARINA SALDIRILDIĞINI BİLİYORUZ. KAMYONUN ARKASINDA GİDECEKSİNİZ. KOKAİNİN HİÇBİR YERE KAYBOLMASINA İZİN VERMEYİN.",
["heist_watchdogs_2_briefing"] = "TAMAM, PLANLADIĞIMIZ GİBİ LİMANA GİDİN. KOKAİNİ PİKAPTAN İNDİRİN. HECTOR'IN TEKNESİNİN YANAŞMASI İÇİN DEPODAN İŞARET VERMENİZ GEREKECEK. TEKNE GELDİĞİNDE KOKAİNİ GÜVERTEYE TAŞIYIN. GERİSİNİ KAPTAN HALLEDER.",
["heist_watchdogs_crimenet"] = "HECTOR, KOKAİN SEVKİYATINA GÖZ KULAK OLACAK ADAMLARA İHTİYAÇ DUYUYOR.$NL;$NL;» KAMYONDAKİ KOKAİNİ KORU$NL;» DEĞİŞEN DURUMLARA UYUM SAĞLA$NL;» LİMANA ULAŞ$NL;» SEVKİYATI TEKNE KAPTANINA TESLİM ET",
["heist_welcome_to_the_jungle_1_briefing"] = "THE ELEPHANT, BİLİM İNSANININ KÜÇÜK CİHAZINI ARAYAN MOTORCU ÇETESİNİN YERİNİ VERDİ. BENCE ADAMI BULMAYA ÇOK YAKLAŞTILAR. ONDAN ÖNCE DAVRANMAK İÇİN ELLERİNDEKİ İSTİHBARATA İHTİYACIMIZ VAR. BAHSE GİRERİM KASALARINDADIR.",
["heist_welcome_to_the_jungle_2_briefing"] = "İSTİHBARATI İNCELEDİM. BU İŞ İLGİNÇ OLACAK. DESTEK SEÇENEKLERİNE BAKIN VE HEPSİNİ İYİCE ÖĞRENİN. BU ADAMIN LABORATUVARINI, LABORATUVARDA DA FÜZYON MOTORUNU BULMAK İÇİN İÇERİ GİZLİCE GİRMEMİZ GEREKİYOR.",
